WITH lines AS (SELECT id, service, host, level, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS attr_key, attr_value) SELECT id, service, host, level, latency_ms, status_code, attr_key, attr_value, CORR(status_code, latency_ms) OVER (PARTITION BY level) AS corr_status_code_latency_ms, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share FROM lines
